 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelLess {
public:
    __aicore__ inline KernelLess() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();
        int64_t offset;
        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            offset = formerLength * blockIdx;
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            offset = formerLength * formerNum + tailLength * tailIdx;
        }
        this->tileLength = tileLength;

        xGm.SetGlobalBuffer((__gm__ T *)x + offset, this->blockLength);
        yGm.SetGlobalBuffer((__gm__ T *)y + offset, this->blockLength);
        zGm.SetGlobalBuffer((__gm__ uint8_t *)z + offset, this->blockLength);

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(uint8_t));

        if constexpr (sizeof(T) == 2) {
            pipe.InitBuffer(castBufX, tileLength * sizeof(float));
            pipe.InitBuffer(castBufY, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t align256Elems = 256 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + align256Elems - 1) / align256Elems) * align256Elems;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        // tail tile: pad input to 256B alignment, but copy out only actual elements
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, tailTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams);
        inQueueX.EnQue(xLocal);

        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();
        AscendC::DataCopyPad(yLocal, yGm[progress * this->tileLength], copyParams);
        inQueueY.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
        AscendC::LocalTensor<uint8_t> zLocal = outQueueZ.AllocTensor<uint8_t>();

        if constexpr (sizeof(T) == 2) {
            AscendC::LocalTensor<float> xCast = castBufX.Get<float>();
            AscendC::LocalTensor<float> yCast = castBufY.Get<float>();
            AscendC::Cast(xCast, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yCast, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Compare(zLocal, xCast, yCast, AscendC::CMPMODE::LT, curTileLength);
        } else {
            AscendC::Compare(zLocal, xLocal, yLocal, AscendC::CMPMODE::LT, curTileLength);
        }

        outQueueZ.EnQue<uint8_t>(zLocal);
        inQueueX.FreeTensor(xLocal);
        inQueueY.FreeTensor(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<uint8_t> zLocal = outQueueZ.DeQue<uint8_t>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint16_t>(curTileLength * sizeof(uint8_t)), 0, 0, 0};
        AscendC::DataCopyPad(zGm[progress * this->tileLength], zLocal, copyParams);
        outQueueZ.FreeTensor(zLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX, inQueueY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufX, castBufY;
    AscendC::GlobalTensor<T> xGm, yGm;
    AscendC::GlobalTensor<uint8_t> zGm;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void less_kernel(
    GM_ADDR x, GM_ADDR y, GM_ADDR z,
    int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength,
    int64_t dtypeSize, int64_t isBfloat16)
{
    if (dtypeSize == 2 && isBfloat16) {
        KernelLess<AscendC::bfloat16_t> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeSize == 2) {
        KernelLess<half> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeSize == 4) {
        KernelLess<float> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeSize == 8) {
        KernelLess<int64_t> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else if (dtypeSize == 1) {
        KernelLess<int8_t> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
