#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_less_kernel.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor less(const at::Tensor &x1, const at::Tensor &x2)
{
    // ---- input validation ----
    TORCH_CHECK(x1.scalar_type() == x2.scalar_type(),
                "less: x1 and x2 must have the same dtype, got ", x1.scalar_type(), " and ", x2.scalar_type());
    TORCH_CHECK(x1.sizes() == x2.sizes(),
                "less: x1 and x2 must have the same shape, got ", x1.sizes(), " and ", x2.sizes());

    auto dtype = x1.scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kBFloat16 ||
                dtype == at::kFloat || dtype == at::kInt ||
                dtype == at::kLong || dtype == at::kChar || dtype == at::kByte,
                "less: unsupported dtype ", dtype);

    // output is always bool
    at::Tensor output = at::empty(x1.sizes(), x1.options().dtype(at::kBool));

    int64_t totalLength = x1.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = x1.element_size();
    int64_t isBfloat16 = (dtype == at::kBFloat16) ? 1 : 0;

    // ---- get hardware parameters ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- block-level tiling (cache line 512B alignment) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB-level tiling ----
    // bufferCoefficient: bytes per element in UB from UB allocation table
    // fp16/bf16 (sizeof=2, needs fp32 cast): inX(2B*2) + inY(2B*2) + castX(4B) + castY(4B) + out(1B*2) = 18
    // fp32/int32 (sizeof=4, direct): inX(4B*2) + inY(4B*2) + out(1B*2) = 18
    // int8/uint8 (sizeof=1, direct): inX(1B*2) + inY(1B*2) + out(1B*2) = 6
    // int64 (sizeof=8, direct): inX(8B*2) + inY(8B*2) + out(1B*2) = 34
    int64_t bufferCoefficient;
    if (dtypeSize == 1) {
        bufferCoefficient = 6;
    } else if (dtypeSize == 2) {
        bufferCoefficient = 18;  // fp16/bf16 with fp32 cast
    } else if (dtypeSize == 8) {
        bufferCoefficient = 34;
    } else {
        bufferCoefficient = 18;  // fp32/int32 (sizeof=4)
    }

