15	template <typename T>
16	class KernelLess {
17	public:
18	    __aicore__ inline KernelLess() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	        int64_t offset;
26	        if (blockIdx < formerNum) {
27	            this->blockLength = formerLength;
28	            offset = formerLength * blockIdx;
29	        } else {
30	            this->blockLength = tailLength;
31	            int64_t tailIdx = blockIdx - formerNum;
32	            offset = formerLength * formerNum + tailLength * tailIdx;
33	        }
34	        this->tileLength = tileLength;
35	
36	        xGm.SetGlobalBuffer((__gm__ T *)x + offset, this->blockLength);
37	        yGm.SetGlobalBuffer((__gm__ T *)y + offset, this->blockLength);
38	        zGm.SetGlobalBuffer((__gm__ uint8_t *)z + offset, this->blockLength);
39	
40	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
41	        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
42	        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(uint8_t));
43	
44	        if constexpr (sizeof(T) == 2) {
45	            pipe.InitBuffer(castBufX, tileLength * sizeof(float));
46	            pipe.InitBuffer(castBufY, tileLength * sizeof(float));
47	        }
48	    }
49	
50	    __aicore__ inline void Process()
51	    {
52	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
53	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
54	
55	        int64_t align256Elems = 256 / static_cast<int64_t>(sizeof(T));
56	        int64_t alignedTailLen = ((tailTileLength + align256Elems - 1) / align256Elems) * align256Elems;
57	
58	        for (int64_t i = 0; i < tileNum - 1; ++i) {
59	            CopyIn(i, this->tileLength);
60	            Compute(i, this->tileLength);
61	            CopyOut(i, this->tileLength);
62	        }
63	        // tail tile: pad input to 256B alignment, but copy out only actual elements
64	        if (tileNum > 0) {
65	            CopyIn(tileNum - 1, alignedTailLen);
66	            Compute(tileNum - 1, alignedTailLen);
67	            CopyOut(tileNum - 1, tailTileLength);
68	        }
69	    }
70	
71	private:
72	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
73	    {
74	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
75	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint16_t>(curTileLength * sizeof(T)), 0, 0, 0};
76	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams);
77	        inQueueX.EnQue(xLocal);
78	
79	        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();
80	        AscendC::DataCopyPad(yLocal, yGm[progress * this->tileLength], copyParams);
81	        inQueueY.EnQue(yLocal);
82	    }
83	
84	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
85	    {
86	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
87	        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
88	        AscendC::LocalTensor<uint8_t> zLocal = outQueueZ.AllocTensor<uint8_t>();
89	
90	        if constexpr (sizeof(T) == 2) {
91	            AscendC::LocalTensor<float> xCast = castBufX.Get<float>();
92	            AscendC::LocalTensor<float> yCast = castBufY.Get<float>();
93	            AscendC::Cast(xCast, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
94	            AscendC::Cast(yCast, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
95	            AscendC::Compare(zLocal, xCast, yCast, AscendC::CMPMODE::LT, curTileLength);
96	        } else {
97	            AscendC::Compare(zLocal, xLocal, yLocal, AscendC::CMPMODE::LT, curTileLength);
98	        }
99	
100	        outQueueZ.EnQue<uint8_t>(zLocal);
101	        inQueueX.FreeTensor(xLocal);
102	        inQueueY.FreeTensor(yLocal);
103	    }
104	
105	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
106	    {
107	        AscendC::LocalTensor<uint8_t> zLocal = outQueueZ.DeQue<uint8_t>();
108	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint16_t>(curTileLength * sizeof(uint8_t)), 0, 0, 0};
109	        AscendC::DataCopyPad(zGm[progress * this->tileLength], zLocal, copyParams);
110	        outQueueZ.FreeTensor(zLocal);
111	    }
112	
113	private:
114	    AscendC::TPipe pipe;
115	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX, inQueueY;
116	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
117	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufX, castBufY;
118	    AscendC::GlobalTensor<T> xGm, yGm;
119	    AscendC::GlobalTensor<uint8_t> zGm;
