#include "kernel_operator.h"

constexpr int32_t NB = 2;

// ============================================================================
// float32 direct: Sub(y-x) -> Max(0) -> Muls(scale) -> Min(1) -> Cast(int32)
// ============================================================================
struct LessFloat32 {
    AscendC::TPipe p;
    AscendC::TQue<AscendC::TPosition::VECIN, NB> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, NB> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wBuf;
    AscendC::GlobalTensor<float> gX, gY;
    AscendC::GlobalTensor<int32_t> gZ;
    int64_t bL, tL;

    __aicore__ inline void init(GM_ADDR i1, GM_ADDR i2, GM_ADDR o, int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
        int64_t bidx = AscendC::GetBlockIdx();
        if (bidx < fn) {
            bL = fl; int64_t off = fl * bidx;
            gX.SetGlobalBuffer((__gm__ float *)i1 + off, fl);
            gY.SetGlobalBuffer((__gm__ float *)i2 + off, fl);
            gZ.SetGlobalBuffer((__gm__ int32_t *)o + off, fl);
        } else {
            bL = tl; int64_t ti = bidx - fn; int64_t off = fl * fn + tl * ti;
            gX.SetGlobalBuffer((__gm__ float *)i1 + off, tl);
            gY.SetGlobalBuffer((__gm__ float *)i2 + off, tl);
            gZ.SetGlobalBuffer((__gm__ int32_t *)o + off, tl);
        }
        tL = tlen;
        p.InitBuffer(qX, NB, tlen * 4);
        p.InitBuffer(qY, NB, tlen * 4);
        p.InitBuffer(qZ, NB, tlen * 4);
        p.InitBuffer(wBuf, tlen * 12); // 3 x tileLen floats: diff, zero, ones
    }
    __aicore__ inline void process() {
        int64_t tn = (bL + tL - 1) / tL, tail = bL - (tn - 1) * tL;
        for (int64_t i = 0; i < tn; ++i) { int64_t c = i == tn - 1 ? tail : tL; ci(i, c); cm(c); co(i, c); }
    }
    __aicore__ inline void ci(int64_t pr, int64_t l) {
        {
            auto x = qX.AllocTensor<float>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * 4), 0, 0, 0};
            AscendC::DataCopyPadExtParams<float> pp{true, 0, 0, 0.0f}; AscendC::DataCopyPad(x, gX[pr * tL], cp, pp); qX.EnQue(x);
        }
        {
            auto y = qY.AllocTensor<float>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * 4), 0, 0, 0};
            AscendC::DataCopyPadExtParams<float> pp{true, 0, 0, 0.0f}; AscendC::DataCopyPad(y, gY[pr * tL], cp, pp); qY.EnQue(y);
        }
    }
    __aicore__ inline void cm(int64_t l) {
        auto x = qX.DeQue<float>(); auto y = qY.DeQue<float>(); auto z = qZ.AllocTensor<int32_t>();
        auto w = wBuf.Get<float>(tL * 3); auto d = w, zero = w[tL], one = w[tL * 2];
        // diff = y - x
        AscendC::Sub(d, y, x, l);
        // zero = 0
        AscendC::Duplicate(zero, 0.0f, l);
        // d = max(diff, 0) → clamps negatives to 0
        AscendC::Max(d, d, zero, l);
        // scale up so any positive diff > 1
        AscendC::Muls(d, d, 1e12f, l);
        // one = 1
        AscendC::Duplicate(one, 1.0f, l);
        // d = min(d, 1) → clamps to [0, 1]
        AscendC::Min(d, d, one, l);
        // cast to int32
        AscendC::Cast(z, d, AscendC::RoundMode::CAST_RINT, l);
        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
    }
    __aicore__ inline void co(int64_t pr, int64_t l) {
        auto z = qZ.DeQue<int32_t>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * 4), 0, 0, 0};
        AscendC::DataCopyPad(gZ[pr * tL], z, cp); qZ.FreeTensor(z);
    }
};

// ============================================================================
// int32: Sub(y-x) → Max(0) → Min(1) → result is already 0 or 1
// ============================================================================
struct LessInt32 {
    AscendC::TPipe p;
    AscendC::TQue<AscendC::TPosition::VECIN, NB> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, NB> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wBuf;
    AscendC::GlobalTensor<int32_t> gX, gY, gZ;
    int64_t bL, tL;

    __aicore__ inline void init(GM_ADDR i1, GM_ADDR i2, GM_ADDR o, int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
        int64_t bidx = AscendC::GetBlockIdx();
        if (bidx < fn) {
            bL = fl; int64_t off = fl * bidx;
            gX.SetGlobalBuffer((__gm__ int32_t *)i1 + off, fl);
            gY.SetGlobalBuffer((__gm__ int32_t *)i2 + off, fl);
            gZ.SetGlobalBuffer((__gm__ int32_t *)o + off, fl);
        } else {
            bL = tl; int64_t ti = bidx - fn; int64_t off = fl * fn + tl * ti;
            gX.SetGlobalBuffer((__gm__ int32_t *)i1 + off, tl);
            gY.SetGlobalBuffer((__gm__ int32_t *)i2 + off, tl);
            gZ.SetGlobalBuffer((__gm__ int32_t *)o + off, tl);
        }
        tL = tlen;
        p.InitBuffer(qX, NB, tlen * 4);
        p.InitBuffer(qY, NB, tlen * 4);
        p.InitBuffer(qZ, NB, tlen * 4);
        p.InitBuffer(wBuf, tlen * 8); // 2 x tileLen int32: diff, zero/one
    }
    __aicore__ inline void process() {
        int64_t tn = (bL + tL - 1) / tL, tail = bL - (tn - 1) * tL;
        for (int64_t i = 0; i < tn; ++i) { int64_t c = i == tn - 1 ? tail : tL; ci(i, c); cm(c); co(i, c); }
    }
    __aicore__ inline void ci(int64_t pr, int64_t l) {
        {
            auto x = qX.AllocTensor<int32_t>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * 4), 0, 0, 0};
            AscendC::DataCopyPadExtParams<int32_t> pp{true, 0, 0, 0}; AscendC::DataCopyPad(x, gX[pr * tL], cp, pp); qX.EnQue(x);
        }
        {
            auto y = qY.AllocTensor<int32_t>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * 4), 0, 0, 0};
            AscendC::DataCopyPadExtParams<int32_t> pp{true, 0, 0, 0}; AscendC::DataCopyPad(y, gY[pr * tL], cp, pp); qY.EnQue(y);
        }
    }
    __aicore__ inline void cm(int64_t l) {
        auto x = qX.DeQue<int32_t>(); auto y = qY.DeQue<int32_t>(); auto z = qZ.AllocTensor<int32_t>();
        auto w = wBuf.Get<int32_t>(tL * 2); auto d = w, zero = w[tL];
        // diff = y - x
        AscendC::Sub(d, y, x, l);
        // zero = 0
        AscendC::Duplicate(zero, (int32_t)0, l);
        // z = max(diff, 0) → >0 when x<y, =0 when x>=y
        AscendC::Max(z, d, zero, l);
        // z = min(z, 1) → clamps to [0, 1]
        AscendC::Duplicate(zero, (int32_t)1, l);
        AscendC::Min(z, z, zero, l);
        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
    }
    __aicore__ inline void co(int64_t pr, int64_t l) {
        auto z = qZ.DeQue<int32_t>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * 4), 0, 0, 0};
        AscendC::DataCopyPad(gZ[pr * tL], z, cp); qZ.FreeTensor(z);
    }
};

// ============================================================================
// half/bf16: Cast → float32 → same logic. 2 bufs: castBuf (2x tileLen) + wBuf (3x tileLen)
// ============================================================================
template <typename SrcT>
struct LessFp16Like {
    AscendC::TPipe p;
    AscendC::TQue<AscendC::TPosition::VECIN, NB> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, NB> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cBuf, wBuf;
    AscendC::GlobalTensor<SrcT> gX, gY;
