    }
    __aicore__ inline void cm(int64_t l) {
        auto x = qX.DeQue<int64_t>(); auto y = qY.DeQue<int64_t>(); auto z = qZ.AllocTensor<int32_t>();
        auto w = wBuf.Get<int64_t>(tL * 2); auto d = w, zero = w[tL];
        // diff = y - x
        AscendC::Sub(d, y, x, l);
        // zero = 0
        AscendC::Duplicate(zero, (int64_t)0, l);
        // d = max(diff, 0)
        AscendC::Max(d, d, zero, l);
        // one = 1
        AscendC::Duplicate(zero, (int64_t)1, l);
        // d = min(d, 1) → 0 or 1
        AscendC::Min(d, d, zero, l);
        // cast to int32 output
        AscendC::Cast(z, d, AscendC::RoundMode::CAST_NONE, l);
        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
    }
    __aicore__ inline void co(int64_t pr, int64_t l) {
        auto z = qZ.DeQue<int32_t>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * 4), 0, 0, 0};
        AscendC::DataCopyPad(gZ[pr * tL], z, cp); qZ.FreeTensor(z);
    }
};

// ============================================================================
// int8/uint8: Cast half → Cast float32 → compute
// ============================================================================
template <typename SrcT>
struct LessIntLike {
    AscendC::TPipe p;
    AscendC::TQue<AscendC::TPosition::VECIN, NB> qX, qY;
    AscendC::TQue<AscendC::TPosition::VECOUT, NB> qZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> hBuf, cBuf, wBuf;
    AscendC::GlobalTensor<SrcT> gX, gY;
    AscendC::GlobalTensor<int32_t> gZ;
    int64_t bL, tL;
    static constexpr int64_t sz = sizeof(SrcT);

    __aicore__ inline void init(GM_ADDR i1, GM_ADDR i2, GM_ADDR o, int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
        int64_t bidx = AscendC::GetBlockIdx();
        if (bidx < fn) {
            bL = fl; int64_t off = fl * bidx;
            gX.SetGlobalBuffer((__gm__ SrcT *)i1 + off, fl);
            gY.SetGlobalBuffer((__gm__ SrcT *)i2 + off, fl);
            gZ.SetGlobalBuffer((__gm__ int32_t *)o + off, fl);
        } else {
            bL = tl; int64_t ti = bidx - fn; int64_t off = fl * fn + tl * ti;
            gX.SetGlobalBuffer((__gm__ SrcT *)i1 + off, tl);
            gY.SetGlobalBuffer((__gm__ SrcT *)i2 + off, tl);
            gZ.SetGlobalBuffer((__gm__ int32_t *)o + off, tl);
        }
        tL = tlen;
        p.InitBuffer(qX, NB, tlen * sz);
        p.InitBuffer(qY, NB, tlen * sz);
        p.InitBuffer(qZ, NB, tlen * 4);
        p.InitBuffer(hBuf, tlen * 4);   // 2 x tileLen half
        p.InitBuffer(cBuf, tlen * 8);   // 2 x tileLen float
        p.InitBuffer(wBuf, tlen * 12);  // 3 x tileLen float
    }
    __aicore__ inline void process() {
        int64_t tn = (bL + tL - 1) / tL, tail = bL - (tn - 1) * tL;
        for (int64_t i = 0; i < tn; ++i) { int64_t c = i == tn - 1 ? tail : tL; ci(i, c); cm(c); co(i, c); }
    }
    __aicore__ inline void ci(int64_t pr, int64_t l) {
        {
            auto x = qX.AllocTensor<SrcT>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * sz), 0, 0, 0};
            AscendC::DataCopyPadExtParams<SrcT> pp{true, 0, 0, static_cast<SrcT>(0)}; AscendC::DataCopyPad(x, gX[pr * tL], cp, pp); qX.EnQue(x);
        }
        {
            auto y = qY.AllocTensor<SrcT>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * sz), 0, 0, 0};
            AscendC::DataCopyPadExtParams<SrcT> pp{true, 0, 0, static_cast<SrcT>(0)}; AscendC::DataCopyPad(y, gY[pr * tL], cp, pp); qY.EnQue(y);
        }
    }
    __aicore__ inline void cm(int64_t l) {
        auto x = qX.DeQue<SrcT>(); auto y = qY.DeQue<SrcT>(); auto z = qZ.AllocTensor<int32_t>();
        // SrcT → half
        auto hf = hBuf.Get<half>(tL * 2); auto xh = hf, yh = hf[tL];
        AscendC::Cast(xh, x, AscendC::RoundMode::CAST_NONE, l);
        AscendC::Cast(yh, y, AscendC::RoundMode::CAST_NONE, l);
        // half → float32
        auto cf = cBuf.Get<float>(tL * 2); auto xf = cf, yf = cf[tL];
        AscendC::Cast(xf, xh, AscendC::RoundMode::CAST_NONE, l);
        AscendC::Cast(yf, yh, AscendC::RoundMode::CAST_NONE, l);
        // Compute less-than
        auto w = wBuf.Get<float>(tL * 3); auto d = w, zero = w[tL], one = w[tL * 2];
        AscendC::Sub(d, yf, xf, l);
        AscendC::Duplicate(zero, 0.0f, l);
        AscendC::Max(d, d, zero, l);
        AscendC::Muls(d, d, 1e12f, l);
        AscendC::Duplicate(one, 1.0f, l);
        AscendC::Min(d, d, one, l);
        AscendC::Cast(z, d, AscendC::RoundMode::CAST_RINT, l);
        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
    }
    __aicore__ inline void co(int64_t pr, int64_t l) {
        auto z = qZ.DeQue<int32_t>(); AscendC::DataCopyExtParams cp{1, (uint32_t)(l * 4), 0, 0, 0};
        AscendC::DataCopyPad(gZ[pr * tL], z, cp); qZ.FreeTensor(z);
    }
};

// dtypeCode: 0=float16, 1=bfloat16, 2=float32, 3=int32, 4=int64, 5=int8, 6=uint8
extern "C" __global__ __aicore__ void less_kernel(
    GM_ADDR i1, GM_ADDR i2, GM_ADDR o, int64_t fN, int64_t fL, int64_t tL, int64_t tLen, int64_t dC)
{
    if (dC == 0)      { LessFp16Like<half> op; op.init(i1, i2, o, fN, fL, tL, tLen); op.process(); }
    else if (dC == 1) { LessFp16Like<bfloat16_t> op; op.init(i1, i2, o, fN, fL, tL, tLen); op.process(); }
    else if (dC == 2) { LessFloat32 op; op.init(i1, i2, o, fN, fL, tL, tLen); op.process(); }
    else if (dC == 3) { LessInt32 op; op.init(i1, i2, o, fN, fL, tL, tLen); op.process(); }
    else if (dC == 4) { LessInt64 op; op.init(i1, i2, o, fN, fL, tL, tLen); op.process(); }
    else if (dC == 5) { LessIntLike<int8_t> op; op.init(i1, i2, o, fN, fL, tL, tLen); op.process(); }
    else              { LessIntLike<uint8_t> op; op.init(i1, i2, o, fN, fL, tL, tLen); op.process(); }
}
