#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_less_kernel.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

// dtypeCategory: 0=float16, 1=bfloat16, 2=float32, 3=int32, 4=int64, 5=int8, 6=uint8
static int64_t getDtypeCategory(at::ScalarType st) {
    switch (st) {
        case at::kHalf:      return 0;
        case at::kBFloat16:  return 1;
        case at::kFloat:     return 2;
        case at::kInt:       return 3;
        case at::kLong:      return 4;
        case at::kChar:      return 5;
        case at::kByte:      return 6;
        default:
            TORCH_CHECK(false, "less: unsupported dtype ", st);
            return -1;
    }
}

// bufferCoefficient lookup by dtypeCategory
static int64_t getBufferCoefficient(int64_t dtypeCategory) {
    // UB cost per element varies by type due to work/buffer sizes
    switch (dtypeCategory) {
        case 0: case 1: // half/bf16: 2 queues * NB*2 + 1 outQ*NB*4 + castBuf(8) + wBuf(12) = 4+4+4+8+12 = 32
            return 32;
        case 2: // float32: 2 queues * NB*4 + 1 outQ*NB*4 + wBuf(12) = 8+8+4+12 = 32
            return 32;
        case 3: // int32: 2 queues * NB*4 + 1 outQ*NB*4 + wBuf(8) = 8+8+4+8 = 28
            return 28;
        case 4: // int64: 2 queues * NB*8 + 1 outQ*NB*4 + wBuf(20) = 16+16+4+20 = 56
            return 56;
        case 5: case 6: // int8/uint8: 2 queues * NB*1 + 1 outQ*NB*4 + hBuf(4) + cBuf(8) + wBuf(12) = 2+2+4+4+8+12 = 32
            return 32;
        default:
            return 32;
    }
}

at::Tensor less(const at::Tensor &input1, const at::Tensor &input2)
{
    // ---- input validation ----
    TORCH_CHECK(input1.scalar_type() == input2.scalar_type(),
                "less: input1 and input2 must have the same dtype");
    TORCH_CHECK(input1.sizes() == input2.sizes(),
                "less: input1 and input2 must have the same shape");

    at::ScalarType dtype = input1.scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kFloat || dtype == at::kBFloat16 ||
                dtype == at::kInt || dtype == at::kLong ||
                dtype == at::kChar || dtype == at::kByte,
                "less: only fp16/fp32/bf16/int32/int64/int8/uint8 are supported, got ", dtype);

    int64_t totalLength = input1.numel();
    // Output is int32 (0 or 1), model_new_ascendc.py will convert to bool
    auto output = at::empty(input1.sizes(), input1.options().dtype(at::kInt));

    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeCategory = getDtypeCategory(dtype);

    // ---- get hardware parameters ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- block-level tiling (cache line 512B alignment) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB-level tiling ----
    int64_t bufferCoefficient = getBufferCoefficient(dtypeCategory);
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;

    // 32B alignment on input type
    int64_t dtypeSize = input1.element_size();
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements < 1) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    // 256B alignment for float32 compute path (Sub/Max/Min ops)
    int64_t computeAlignElements = 256 / static_cast<int64_t>(sizeof(float));
    tileLength = (tileLength / computeAlignElements) * computeAlignElements;

    if (tileLength == 0) {
        tileLength = computeAlignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // All args must be lvalues
    int64_t fnVal = formerNum;
    int64_t flVal = formerLength;
    int64_t tlVal = tailLength;
    int64_t tLenVal = tileLength;
    int64_t dcVal = dtypeCategory;

    EXEC_KERNEL_CMD(less_kernel, blockDim,
                    input1, input2, output,
                    fnVal, flVal, tlVal, tLenVal, dcVal);

    return output;
}

}  // namespace ascend_kernel
