    # fallback: direct .so loading
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    """Less operator: element-wise x1 < x2 comparison using AscendC kernel."""

    def __init__(self):
        super().__init__()

    def forward(self, x1: torch.Tensor, x2: torch.Tensor) -> torch.Tensor:
        # Kernel produces int32 output (0/1), convert to bool to match model.py
        result = torch.ops.npu.less(x1, x2)
